import { IDisplayRequestBase } from "#core/ui/context-manager/display-queue-manager.js";
import {
	Catalog,
	CatalogItemCommittedEvent,
	CatalogItemCommittedEventName,
} from "#core/ui/utilities/utility-serialize.js";

import { QuestItem } from "#base/ui/quest-tracker/quest-item.js";
import { getQuestTracker, QuestTrackerRefreshRequestName } from "#base/ui/quest-tracker/quest-tracker.js";
import { TriumphData } from "#base/ui-next/screens/legacies/legacies-model.js";

const VERSION = 2; // Written to disk; increment if data structure changes.
const TRACKED_TRIUMPH_OBJECT_NAME = "tracked-triumphs";
const PENDING_TRIUMPH_OBJECT_NAME = "pending-to-untrack";
const TRACKED_TRIUMPH_KEY_NAME = "ids";

export interface TriumphCompletePopupData extends IDisplayRequestBase {
	triumphData: TriumphData;
}

export class TriumphTrackingManagerClass {
	private readonly triumphCatalogName = "TriumphTrackerCatalog";
	private catalog: Catalog;
	private playerId: PlayerId;
	private isCatalogValueReady = true;

	constructor(playerId: PlayerId) {
		this.playerId = playerId;
		this.catalog = new Catalog({
			name: this.triumphCatalogName,
			version: VERSION,
			player: Players.get(playerId),
		});

		if (!this.catalog.justCreated) {
			this.readTrackedTriumphs();
		}

		engine.on("BeforeUnload", this.beforeUnload, this);
		engine.on("PlayerLegacyProgress", this.onLegacyProgress, this);
		window.addEventListener(CatalogItemCommittedEventName, this.onCatalogCommited);
	}

	private beforeUnload() {
		engine.off("BeforeUnload", this.beforeUnload, this);
		engine.off("PlayerLegacyProgress", this.onLegacyProgress, this);
		window.removeEventListener(CatalogItemCommittedEventName, this.onCatalogCommited);
	}

	private onLegacyProgress(event: PlayerLegacyProgress_EventData) {
		if (event.player != this.playerId) {
			return;
		}

		const legacyDef = GameInfo.Legacies.lookup(event.legacy);
		if (!legacyDef) {
			console.error("triumph-tracking-manager.ts: ");
			return;
		}

		const questTracker = getQuestTracker();
		if (questTracker.has(legacyDef.LegacyType, "triumph")) {
			this.addTriumphToQuestTracker(legacyDef);
		}
	}

	private onCatalogCommited = (event: CatalogItemCommittedEvent) => {
		if (this.playerId != event.detail.playerId) {
			return;
		}

		if (event.detail.objectId === TRACKED_TRIUMPH_OBJECT_NAME && event.detail.key === TRACKED_TRIUMPH_KEY_NAME) {
			this.readTrackedTriumphs();
			this.isCatalogValueReady = true;
		}
	};

	/**
	 * Public exposure for tracked triumphs to be (re-)sent to quest tracker.
	 * Required for hotseat when switching players.
	 */
	public refreshQuestTracker() {
		this.checkForPendingToUntrack();
		if (this.isCatalogValueReady) {
			this.readTrackedTriumphs();
		}
	}

	// Check if we have a pending Triumph to untrack on this player's turn
	private checkForPendingToUntrack() {
		// Check on all catalogs to see if one of them has a pending triumph removal
		const tracker = instances.find(
			(tracker) =>
				tracker.catalog.getObject(PENDING_TRIUMPH_OBJECT_NAME).read(TRACKED_TRIUMPH_KEY_NAME) != "" &&
				tracker.catalog.getObject(PENDING_TRIUMPH_OBJECT_NAME).read(TRACKED_TRIUMPH_KEY_NAME) != null,
		);

		// No triumph to delete found
		if (tracker == undefined) {
			return;
		}

		const pendingToUntrack = tracker.catalog
			.getObject(PENDING_TRIUMPH_OBJECT_NAME)
			.read(TRACKED_TRIUMPH_KEY_NAME) as string;

		// If the tracker player and current player are the same, check for existence in tracker's catalog
		if (tracker.playerId == GameContext.localObserverID) {
			const trackedTriumphs = this.catalog
				.getObject(TRACKED_TRIUMPH_OBJECT_NAME)
				.read(TRACKED_TRIUMPH_KEY_NAME) as string;
			const existsInTrackedTriumphs = trackedTriumphs.includes(pendingToUntrack);
			// The triumph was deleted on the original catalog, remove it from pending.
			if (!existsInTrackedTriumphs) {
				this.catalog.getObject(PENDING_TRIUMPH_OBJECT_NAME).write(TRACKED_TRIUMPH_KEY_NAME, "");
				return;
			}
		}

		const legacyDef = GameInfo.Legacies.lookup(pendingToUntrack);
		if (legacyDef == null) {
			console.log(
				"triumph-tracking-manager: couldn't to find legacy definition for triumph type: " + pendingToUntrack,
			);
			return;
		}

		this.unTrackTriumph(legacyDef);
	}

	// Parse the tracked triumphs from disk and add them to the quest tracker
	private readTrackedTriumphs() {
		const serializedTriumphIDs = this.catalog
			.getObject(TRACKED_TRIUMPH_OBJECT_NAME)
			.read(TRACKED_TRIUMPH_KEY_NAME) as string;

		if (!serializedTriumphIDs || serializedTriumphIDs == "") {
			//nothing to deserialize
			return;
		}

		const unserializedTriumphIDs = serializedTriumphIDs.split("|");
		unserializedTriumphIDs.forEach((triumphID) => {
			const legacyDefinition = GameInfo.Legacies.lookup(triumphID);
			if (legacyDefinition == null) {
				console.error(
					"triumph-tracking-manager: unable to find legacy definition for triumph of type: " + triumphID,
				);
				return;
			}

			this.addTriumphToQuestTracker(legacyDefinition);
		});
	}

	//Do the actual adding the triumph to the quest tracker
	private addTriumphToQuestTracker(triumph: LegacyDefinition) {
		const localPlayerLegacies = Players.get(this.playerId)?.Legacies;
		if (!localPlayerLegacies) {
			console.error("triumph-tracking-manager: unable to get legacies object for local player: " + this.playerId);
			return;
		}

		const triumphQuestItem: QuestItem = {
			id: triumph.LegacyType,
			title: Locale.compose(triumph.Name),
			description: triumph.TriggerDescription,
			getCurrentProgress: () => {
				const progress = localPlayerLegacies.getProgress(triumph.LegacyType)?.progress;
				if (!progress || !progress[0].current) {
					//This can be null if the player has not made any progress on this triumph
					return "0";
				}
				return progress[0].current.toString();
			},
			getCurrentGoal: () => {
				const progress = localPlayerLegacies.getProgress(triumph.LegacyType)?.progress;
				if (!progress || !progress[0].total) {
					console.error(
						"triumph-tracking-manager: unable to get total progress of triumph of type: " +
							triumph.LegacyType,
					);
					return "0";
				}
				return progress[0].total.toString();
			},
			system: "triumph",
			progressType: "",
		};

		const questTracker = getQuestTracker();
		questTracker.add(triumphQuestItem);
	}

	//Add triumph to quest tracker and write the new list of tracked triumphs to disk
	trackTriumph(triumph: LegacyDefinition) {
		this.addTriumphToQuestTracker(triumph);
		this.writeTrackedLegacies();
	}

	//Remove triumph from the quest tracker and write the new list to disk
	unTrackTriumph(triumph: LegacyDefinition) {
		const questTracker = getQuestTracker();
		if (questTracker.has(triumph.LegacyType, "triumph")) {
			questTracker.remove(triumph.LegacyType, "triumph");
		}
		this.writeTrackedLegacies();
	}

	setTriumphToUntrack(triumph: LegacyDefinition) {
		this.catalog.getObject(PENDING_TRIUMPH_OBJECT_NAME).write(TRACKED_TRIUMPH_KEY_NAME, triumph.LegacyType);
	}

	onClickTrackTriumph(legacyType: string): void {
		const legacy = GameInfo.Legacies.lookup(legacyType);
		if (!legacy) {
			console.error("legacies-model: unable to get legacy definition of legacy of type: " + legacyType);
			return;
		}

		const questTracker = getQuestTracker();
		if (questTracker.has(legacyType, "triumph")) {
			this.unTrackTriumph(legacy);
		} else {
			this.trackTriumph(legacy);
		}
	}

	//Do the actual serialization and writing to disk
	private writeTrackedLegacies() {
		let serializedTriumphIDs = "";
		const questTracker = getQuestTracker();
		const allQuestitems = Array.from(questTracker.getItems());
		allQuestitems.forEach((questItem) => {
			if (questItem.system != "triumph") {
				return;
			}
			if (serializedTriumphIDs == "") {
				serializedTriumphIDs = questItem.id;
				return;
			}
			serializedTriumphIDs += "|" + questItem.id;
		});
		this.catalog.getObject(TRACKED_TRIUMPH_OBJECT_NAME).write(TRACKED_TRIUMPH_KEY_NAME, serializedTriumphIDs);
		this.isCatalogValueReady = false;
	}
}

/**
 * Multiple instances of TriumphTrackingManager are supported in the case of hotseat.
 * (Typical case is just one to be instanced in a single player or MP game.)
 */
const instances: TriumphTrackingManagerClass[] = [];
export function getTriumphTrackingManager(): TriumphTrackingManagerClass {
	const playerId = GameContext.localObserverID;
	if (playerId > 999) {
		// Exteremely unlikely that we'll have more than 8 players, but safety regardless.
		throw new Error(`triumph-tracker-manager: Player ID of "${playerId}" exceeds maximum supported value of 999.`);
	}
	if (!instances[playerId]) {
		instances[playerId] = new TriumphTrackingManagerClass(playerId);
	}
	return instances[playerId];
}
window.addEventListener(QuestTrackerRefreshRequestName, () => {
	// Refresh the triumph tracking manager when the quest tracker is refreshed to ensure that tracked triumphs are re-added to the quest tracker
	getTriumphTrackingManager().refreshQuestTracker();
});
getTriumphTrackingManager(); // Instantiate manager for whichever player is currently active.
